import { Pressable, StyleSheet, Text, View } from "react-native";
import { useState } from "react";
import type { StyleProp, TextStyle, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface ChipOption {
  value: string;
  label: string;
}

export interface ChipGroupProps {
  options: ChipOption[];
  value: string[];
  onValueChange: (value: string[]) => void;
  label: string;
  multiple?: boolean;
  /** How many chips show before the rest collapse into a "+N more" chip. */
  maxVisible?: number;
  /** Style of the group wrapper. */
  style?: StyleProp<ViewStyle>;
  /** Extend the inner, named parts of the chip group: chip, selected, chipText or more. The React Native counterpart of `classNames`. */
  styles?: {
    chip?: StyleProp<ViewStyle>;
    selected?: StyleProp<ViewStyle>;
    chipText?: StyleProp<TextStyle>;
    more?: StyleProp<ViewStyle>;
  };
}

export function ChipGroup({ options, value, onValueChange, label, multiple = true, maxVisible = Infinity, style, styles: parts }: ChipGroupProps) {
  const tokens = useTokens();
  const [expanded, setExpanded] = useState(false);
  const shown = expanded ? options : options.slice(0, maxVisible);
  const hidden = options.length - shown.length;

  function toggle(next: string) {
    if (!multiple) return onValueChange(value.includes(next) ? [] : [next]);
    onValueChange(value.includes(next) ? value.filter((entry) => entry !== next) : [...value, next]);
  }

  return (
    <View accessibilityRole="radiogroup" accessibilityLabel={label} style={[local.group, style]}>
      {shown.map((option) => {
        const selected = value.includes(option.value);
        return (
          <Pressable
            key={option.value}
            accessibilityRole={multiple ? "checkbox" : "radio"}
            accessibilityState={{ checked: selected }}
            onPress={() => toggle(option.value)}
            style={[
              local.chip,
              { borderColor: selected ? tokens.foreground : tokens.border, backgroundColor: selected ? tokens.foreground : tokens.surface },
              parts?.chip,
              selected && parts?.selected,
            ]}
          >
            <Text style={[{ color: selected ? tokens.background : tokens.foreground, fontSize: metrics.text.sm, fontWeight: "500" }, parts?.chipText]}>{option.label}</Text>
          </Pressable>
        );
      })}
      {hidden > 0 ? (
        <Pressable accessibilityRole="button" onPress={() => setExpanded(true)} style={[local.chip, { borderColor: tokens.border, backgroundColor: tokens.surfaceMuted }, parts?.more]}>
          <Text style={{ color: tokens.textSecondary, fontSize: metrics.text.sm, fontWeight: "500" }}>+{hidden} more</Text>
        </Pressable>
      ) : null}
    </View>
  );
}

const local = StyleSheet.create({
  group: { flexDirection: "row", flexWrap: "wrap", gap: metrics.space[2], alignSelf: "stretch" },
  chip: { minHeight: metrics.controlHeight.sm, paddingHorizontal: metrics.space[3], alignItems: "center", justifyContent: "center", borderWidth: 1, borderRadius: 999 },
});

export default ChipGroup;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
